// Karaşimşek: ışık 6 LED üzerinde gidip gelir
const int LEDLER[] = {8, 9, 10, 11, 12, 13};
const int SAYI = 6;
const int BEKLEME = 80;   // ms; küçültürsen hızlanır

void setup() {
  for (int i = 0; i < SAYI; i++) {
    pinMode(LEDLER[i], OUTPUT);
  }
}

void loop() {
  // ileri: 0 -> 5
  for (int i = 0; i < SAYI; i++) {
    digitalWrite(LEDLER[i], HIGH);
    delay(BEKLEME);
    digitalWrite(LEDLER[i], LOW);
  }
  // geri: 4 -> 1 (uçlar iki kez yanmasın)
  for (int i = SAYI - 2; i > 0; i--) {
    digitalWrite(LEDLER[i], HIGH);
    delay(BEKLEME);
    digitalWrite(LEDLER[i], LOW);
  }
}
